/**
 * TTF subset reader — the minimum needed to typeset text with an embedded
 * TrueType font inside a PDF: cmap (format 4/12) for codepoint → glyph-id,
 * head.unitsPerEm, hhea.numberOfHMetrics, hmtx for advance widths.
 * Only the two vendored subsets (docgen-serif.ttf / docgen-serif-bold.ttf,
 * generated by pyftsubset) are ever loaded — small, fixed, tested.
 */
export interface FontData {
  /** unitsPerEm (subsets are 1000). */
  unitsPerEm: number;
  numberOfHMetrics: number;
  advances: number[]; // per-glyph advance (units), numGlyphs entries
  /** cmap: Unicode codepoint → glyph id (best available subtable). */
  charMap: Map<number, number>;
  /** head: glyph-space bbox + hhea vertical metrics (FontDescriptor). */
  bbox: [number, number, number, number];
  ascent: number;
  descent: number;
  capHeight: number;
}

function u16(v: DataView, o: number): number {
  return v.getUint16(o);
}
function i16(v: DataView, o: number): number {
  return v.getInt16(o);
}
function u32(v: DataView, o: number): number {
  return v.getUint32(o);
}

function parseCmap(v: DataView, tableOffset: number): Map<number, number> {
  // Walk the cmap directory; prefer (3,10)/(0,4)/(0,6) format-12, then (3,1)/(0,3) format-4.
  const n = u16(v, tableOffset + 2);
  let best: { platform: number; encoding: number; offset: number } | null = null;
  for (let i = 0; i < n; i++) {
    const platform = u16(v, tableOffset + 4 + i * 8);
    const encoding = u16(v, tableOffset + 6 + i * 8);
    const offset = u32(v, tableOffset + 8 + i * 8);
    // Preference order: Windows BMP/full, then Unicode full.
    const rank = platform === 3 ? (encoding === 10 ? 3 : encoding === 1 ? 2 : 1) : platform === 0 ? (encoding >= 4 ? 2 : 1) : 0;
    if (!best || rank > best.platform) best = { platform: rank, encoding, offset: tableOffset + offset };
  }
  const map = new Map<number, number>();
  if (!best) return map;
  const fmt = u16(v, best.offset);
  if (fmt === 4) {
    const segCountX2 = u16(v, best.offset + 6);
    const segCount = segCountX2 / 2;
    const endCodes = best.offset + 14;
    const startCodes = endCodes + segCountX2 + 2;
    const idDeltas = startCodes + segCountX2;
    const idRangeOffsets = idDeltas + segCountX2;
    for (let i = 0; i < segCount; i++) {
      const end = u16(v, endCodes + i * 2);
      const start = u16(v, startCodes + i * 2);
      const delta = i16(v, idDeltas + i * 2);
      const rangeOffset = u16(v, idRangeOffsets + i * 2);
      if (start === 0xffff) continue;
      for (let c = start; c <= end; c++) {
        let gid: number;
        if (rangeOffset === 0) {
          gid = (c + delta) & 0xffff;
        } else {
          // Address of the glyph index for this code (per spec formula).
          const idxAddr = idRangeOffsets + i * 2 + rangeOffset + (c - start) * 2;
          if (idxAddr + 1 >= v.byteLength) continue;
          const g = u16(v, idxAddr);
          gid = g === 0 ? 0 : (g + delta) & 0xffff;
        }
        if (gid !== 0 && !map.has(c)) map.set(c, gid);
      }
    }
  } else if (fmt === 12) {
    const nGroups = u32(v, best.offset + 12);
    for (let i = 0; i < nGroups; i++) {
      const gOff = best.offset + 16 + i * 12;
      const start = u32(v, gOff);
      const end = u32(v, gOff + 4);
      const startGid = u32(v, gOff + 8);
      for (let c = start; c <= end && c - start < 0x10000; c++) {
        const gid = startGid + (c - start);
        if (gid !== 0 && !map.has(c)) map.set(c, gid);
      }
    }
  }
  return map;
}

export function parseTtf(bytes: Uint8Array): FontData {
  const v = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (u32(v, 0) !== 0x00010000 && u32(v, 0) !== 0x74727565) throw new Error("not a TrueType font");
  const numTables = u16(v, 4);
  let head: { unitsPerEm: number; indexToLocFormat: number; bbox: [number, number, number, number] } | null = null;
  let hhea: { numberOfHMetrics: number; ascent: number; descent: number } | null = null;
  let cmapOffset = -1;
  let hmtxOffset = -1;
  let maxpGlyphs = 0;
  let os2CapHeight = 0;
  for (let i = 0; i < numTables; i++) {
    const rec = 12 + i * 16;
    const tag = String.fromCharCode(v.getUint8(rec), v.getUint8(rec + 1), v.getUint8(rec + 2), v.getUint8(rec + 3));
    const off = u32(v, rec + 8);
    if (tag === "head")
      head = {
        unitsPerEm: u16(v, off + 18),
        indexToLocFormat: i16(v, off + 50),
        bbox: [i16(v, off + 36), i16(v, off + 38), i16(v, off + 40), i16(v, off + 42)],
      };
    else if (tag === "hhea") hhea = { numberOfHMetrics: u16(v, off + 34), ascent: i16(v, off + 4), descent: i16(v, off + 6) };
    else if (tag === "OS/2") {
      // capHeight lives at OS/2 version>=2 offset 88; older versions fall back.
      const version = u16(v, off);
      os2CapHeight = version >= 2 ? i16(v, off + 88) : 0;
    }
    else if (tag === "maxp") maxpGlyphs = u16(v, off + 4);
    else if (tag === "cmap") cmapOffset = off;
    else if (tag === "hmtx") hmtxOffset = off;
  }
  if (!head || !hhea || cmapOffset < 0 || hmtxOffset < 0) throw new Error("required TTF table missing");

  const charMap = parseCmap(v, cmapOffset);

  // hmtx: numberOfHMetrics × (advanceWidth, lsb), then same-advance tail.
  const advances = new Array<number>(maxpGlyphs).fill(0);
  for (let g = 0; g < maxpGlyphs; g++) {
    if (g < hhea.numberOfHMetrics) {
      advances[g] = u16(v, hmtxOffset + g * 4);
    } else {
      advances[g] = advances[hhea.numberOfHMetrics - 1] ?? 0;
    }
  }

  return {
    unitsPerEm: head.unitsPerEm,
    numberOfHMetrics: hhea.numberOfHMetrics,
    advances,
    charMap,
    bbox: head.bbox,
    ascent: hhea.ascent,
    descent: hhea.descent,
    capHeight: os2CapHeight || Math.round(head.unitsPerEm * 0.7),
  };
}

/** Text width in font units (caller converts: units / unitsPerEm * fontSize). */
export function textWidthUnits(font: FontData, codepoints: readonly number[]): number {
  let w = 0;
  for (const cp of codepoints) {
    const gid = font.charMap.get(cp) ?? 0;
    w += font.advances[gid] ?? 0;
  }
  return w;
}
